def main():
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--mode',choices=['default','detail'],required=True);a=p.parse_args();plan=json.loads((HERE/'source-pins.json').read_text());gate=next(g for g in plan['gates'] if g['label']=='verify-no-prover-'+a.mode);r=json.loads((a.run/'receipt.json').read_text());assert r['exit_status']==0;assert r['command']==gate['command'];assert r['source_revision']==plan['after_revision'];assert r['process_swaps']==0 and r['cgroup_swap_current']=='0';assert r['limits']=={'memory.high':'6442450944','memory.max':'8589934592','memory.swap.max':'0'}
