 text=out.decode();cases=[l[l.index('VERIFY_REAL_S2_CASE '):] for l in text.splitlines() if 'VERIFY_REAL_S2_CASE ' in l];assert len(cases)==112;assert sum(' observed=false ' in l for l in cases)==56;assert sum(' observed=true ' in l for l in cases)==56;assert sum('fault=None ' in l for l in cases)==2;assert all('old_new_equal=true ' in l and 'trace_values=0 ' in l for l in cases);assert all('detail_phases='+str(a.mode=='detail').lower()+' ' in l for l in cases);assert 'test result: ok. 1 passed; 0 failed;' in text;assert 'VERIFY_REAL_S2_PASS cases=112 faults=55 rows=14..24 observers=Some,None detail_phases='+str(a.mode=='detail').lower() in text
 summary={'status':'PASS_NO_PROVER_VERIFY_INJECTIONS','mode':a.mode,'source_revision':plan['after_revision'],'source_pins_sha256':sha((HERE/'source-pins.json').read_bytes()),'receipt_sha256':sha((a.run/'receipt.json').read_bytes()),'active_rustc_features':c['active_cfg_features'],'externs':c['externs'],'cases':112,'observer_None':56,'observer_Some':56,'prover':False,'production_trace_values':'disabled and all case snapshots asserted empty','metrics':{k:r[k] for k in ['exit_status','wall_seconds','peak_rss_kib','process_swaps','limits']},'axioms':'N/A: Rust/read-hash stage'}
